	"URL" NVARCHAR2(2000),                                                                                                                                                                                        
	"TYPE" NVARCHAR2(255),                                                                                                                                                                                        
	"SUFFIX" NVARCHAR2(255),                                                                                                                                                                                      
	"SORT_NUM" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                            
